package com.wansheng.visitor.dormitory;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/dormitory")class DormitoryInternalQueryController{private final DormitoryRepository repo;private final String token;DormitoryInternalQueryController(DormitoryRepository r,@Value("${visitor.dormitory.internal-token}")String t){repo=r;token=t;}private void check(String t){if(token.isBlank()||!token.equals(t))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}@GetMapping("/records/{id}/cancellation-status")Map<String,Boolean>cancellationStatus(@PathVariable String id,@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return Map.of("allowed",repo.cancellationAllowed(id));}@GetMapping("/records")List<DormitoryAdminView>records(@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return repo.list(false).stream().map(r->new DormitoryAdminView(r.visitId(),r.visitorName(),r.mobile(),r.hostName(),r.hostDepartment(),r.visitReason(),r.accommodationRequired(),r.bedCode())).toList();}@GetMapping("/audits")List<Map<String,Object>>audits(@RequestHeader(value="X-Internal-Token",required=false)String t){check(t);return repo.audits();}}
